<template><div class="page"><div class="intro"><div><span class="eyebrow">运营数据概览</span><h1>从已有资产开始，制作下一条视频。</h1><p>统一管理素材、口播、模板和成片，服务东南亚不同市场的内容生产。</p></div><el-button type="primary" size="large" @click="$router.push('/assistant')">打开创作助手</el-button></div><div class="stats"><div v-for="item in stats" :key="item.key" class="stat"><span>{{item.label}}</span><strong>{{item.value}}</strong><small>内容资产</small></div></div><div class="grid"><section><div class="section-head"><h3>最近新增素材</h3><el-link @click="$router.push('/assets')">查看全部</el-link></div><el-table :data="assets" stripe><el-table-column prop="name" label="名称"/><el-table-column prop="asset_type" label="类型"/><el-table-column prop="source_platform" label="来源"/></el-table></section><section class="callout"><span class="eyebrow">工作流</span><h3>从参考素材到可复用资产</h3><p>归档素材，关联脚本和模板，并在每个成片中保留完整的内容来源关系。</p><el-button text type="primary" @click="$router.push('/mix-projects')">浏览混剪方案 →</el-button></section></div></div></template>
<script setup lang="ts">import {ref,onMounted} from 'vue'; import axios from 'axios'; const stats=ref<any[]>([]); const assets=ref<any[]>([]); onMounted(async()=>{const [d,a]=await Promise.all([axios.get('/api/dashboard'),axios.get('/api/assets')]); stats.value=[['assets','素材'],['scripts','脚本'],['templates','模板'],['mix_projects','混剪方案'],['videos','视频作品']].map(([key,label])=>({key,label,value:d.data[key]||0})); assets.value=a.data.slice(0,5)})</script>
